impl<T: gx::Real, O: gx::Orientation> Pseudoscalar<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Pseudoscalar<(), T, O> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        let t5 = -t4;
        Pseudoscalar::from_coeffs([t5])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Pseudoscalar::from_coeffs([t0]))
    }

}

impl<T: gx::Real> Pseudoscalar<(), T, gx::Extrinsic> {
    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Rotor<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = -p0;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs_rotation(p1, T::from_i64(0));
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([c0, t0]))
        })
    }

}

impl<T: gx::Coef, O: gx::Orientation> gx::NewtonStep for Pseudoscalar<(), T, O> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t3 = x[0] * T::from_ratio(3, 2);
        let t4 = (-t1).mul_add(T::from_ratio(1, 2), t3);
        Pseudoscalar::from_coeffs([t4])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

